  G={"id":f"4-T{n}","year":"index.html","cls":f"4 клас · Т{n}","title":t['title'],"idleHint":20000,"intro":t['intro'],"learn":t['learn'],
     "mapSay":f"Ось план зали «{h}». Відкривайте вітрини по черзі.","mapDone":"Усі вітрини готові! Відкриймо залу.","finIcon":t['stages'][0]['icon'],"finName":f"Відкрити залу «{h}»",
     "stages":t['stages'],"finale":fin,"T":T}
  for s in G['stages']:
    if s['type']=='pixel':
      for L in s['levels']:assert all(len(r)==len(L['rows'][0]) for r in L['rows'])
    if s['type'] in('doors',):
      for x in s['items']:assert 0<=x['a']<len(x['opts'])
  hh=pat.sub(lambda m:'window.G = '+json.dumps(G,ensure_ascii=False)+';',tpl,count=1)
  hh=re.sub(r'<title>[^<]*</title>',f'<title>4 клас · Т{n} {t["title"]}</title>',hh,count=1)
  open(D+f't{n}.html','w',encoding='utf8').write(hh)
